// 1. Place Limit Order
POST /api/v1/orders
Headers:
  X-Client-Order-Id: cl_ord_991823
Request:
{
  "account_id": "acct_7712",
  "symbol": "AAPL",
  "side": "BUY",
  "order_type": "LIMIT",
  "time_in_force": "GTC",
  "price_ticks": 22550, // $225.50 in integer cents
  "quantity": 100
}
Response (200 OK — Sequenced & Matched):
{
  "order_id": "900182736451",
  "sequence_no": 48192031,
  "status": "PARTIALLY_FILLED",
  "filled_qty": 60,
  "remaining_qty": 40,
  "avg_fill_price_ticks": 22545
}

// ---------------------------------------------------------------------------
// Core Storage Entities & Schema Definitions
// ---------------------------------------------------------------------------
ENTITY orders_sequenced_log (Aeron / Raft Replicated Command Log) {
  [PK ] sequence_no            BIGINT (Monotonic)
  [IDX] order_id               BIGINT
  [IDX] symbol                 VARCHAR(12)
        side_and_type          ENUM('BUY_LIMIT','SELL_LIMIT')
        price_ticks            BIGINT (Cents/Ticks)
}

ENTITY in_memory_order_book (LMAX Single-Threaded RAM State) {
  [PK ] order_id               BIGINT (HashMap O(1))
  [IDX] price_ticks            BIGINT (TreeMap Level)
        remaining_qty          INT
        fifo_prev_ptr          ORDER_NODE_PTR
        fifo_next_ptr          ORDER_NODE_PTR
}

ENTITY trade_executions (TimescaleDB / Clearing Ledger) {
  [PK ] execution_id           BIGINT
  [FK ] buy_order_id           BIGINT
  [FK ] sell_order_id          BIGINT
        exec_price_ticks       BIGINT
        matched_qty            INT
}

// Relationships: orders_sequenced_log --(1 : 1 (populates book node))--> in_memory_order_book --(1 : N (generates fills))--> trade_executions

/*
 * ============================================================================
 * FLOW 1: PRE-TRADE RISK RESERVATION & SEQUENCED INGRESS
 * ============================================================================
 * [Client] --(Place BUY 100 AAPL @ $200)--> [Order GW]
 *   --> [Pre-Trade Risk Shard (AcctId)]: Check & reserve $20,000 in memory
 *   --> [Aeron Raft Sequencer]: Assign seqNo=10492, replicate to 2 followers
 *   --> [LMAX Disruptor Ring Buffer] --> [Single-Threaded LOB Engine]
 *
 * ============================================================================
 * FLOW 2: PRICE-TIME PRIORITY MATCHING & O(1) CANCELLATION
 * ============================================================================
 * [Incoming BUY 100 @ $200.00]
 *   1. Check Asks Min-Tree: Best Ask is $199.80 (Resting Order A: 60 sh, Order B: 80 sh)
 *   2. Match 60 shares against Order A @ $199.80 -> Order A FILLED & unlinked O(1)
 *   3. Match 40 shares against Order B @ $199.80 -> Order B PARTIAL (40 sh left)
 *   4. Emit 2 TradeExecution events (Buyer gets $0.20/sh price improvement!)
 */

package com.exchange.trading.engine;

import com.exchange.trading.domain.*;
import java.util.*;

public final class DeterministicLimitOrderBook {

    private final String symbol;
    private long sequenceNo = 0L;

    // Bids sorted highest price first (Max-Tree); Asks sorted lowest price first (Min-Tree)
    private final NavigableMap<Long, PriceLevel> bids = new TreeMap<>(Comparator.reverseOrder());
    private final NavigableMap<Long, PriceLevel> asks = new TreeMap<>(Long::compareTo);

    // O(1) lookup by orderId for instant cancellation without scanning price levels
    private final Map<Long, OrderNode> orderIndex = new HashMap<>(1_000_000);

    public record MatchFill(long seqNo, long buyOrderId, long sellOrderId, long priceCents, long qty) {}

    public DeterministicLimitOrderBook(String symbol) {
        this.symbol = symbol;
    }

    // Executed exclusively on a single pinned CPU thread (Zero Locks!)
    public List<MatchFill> processLimitOrder(OrderNode incoming) {
        List<MatchFill> fills = new ArrayList<>(4);

        if (incoming.side == Side.BUY) {
            matchIncoming(incoming, asks, bids, true, fills);
        } else {
            matchIncoming(incoming, bids, asks, false, fills);
        }
        return fills;
    }

    private void matchIncoming(
        OrderNode aggressive,
        NavigableMap<Long, PriceLevel> oppositeBook,
        NavigableMap<Long, PriceLevel> sameSideBook,
        boolean isBuy,
        List<MatchFill> fills
    ) {
        while (aggressive.leavesQty > 0 && !oppositeBook.isEmpty()) {
            Map.Entry<Long, PriceLevel> bestEntry = oppositeBook.firstEntry();
            long bestOppositePrice = bestEntry.getKey();

            // Check price crossing condition
            boolean crosses = isBuy
                ? (aggressive.priceCents >= bestOppositePrice)
                : (aggressive.priceCents <= bestOppositePrice);
            if (!crosses) break;

            PriceLevel level = bestEntry.getValue();
            OrderNode resting = level.head;

            // Walk FIFO doubly-linked list at this price level
            while (resting != null && aggressive.leavesQty > 0) {
                OrderNode nextResting = resting.next;
                long tradeQty = Math.min(aggressive.leavesQty, resting.leavesQty);

                aggressive.leavesQty -= tradeQty;
                resting.leavesQty -= tradeQty;
                level.totalVolume -= tradeQty;

                long buyOrderId = isBuy ? aggressive.orderId : resting.orderId;
                long sellOrderId = isBuy ? resting.orderId : aggressive.orderId;

                // Trade always executes at the resting maker order's price!
                fills.add(new MatchFill(++sequenceNo, buyOrderId, sellOrderId, resting.priceCents, tradeQty));

                if (resting.leavesQty == 0) {
                    level.remove(resting);
                    orderIndex.remove(resting.orderId);
                }
                resting = nextResting;
            }

            if (level.head == null) {
                oppositeBook.pollFirstEntry(); // Price level exhausted
            }
        }

        // If unfilled quantity remains on a LIMIT order, rest it on the book
        if (aggressive.leavesQty > 0) {
            PriceLevel targetLevel = sameSideBook.computeIfAbsent(aggressive.priceCents, PriceLevel::new);
            targetLevel.append(aggressive);
            orderIndex.put(aggressive.orderId, aggressive);
        }
    }

    // O(1) Order Cancellation via HashMap + Doubly-Linked List pointer manipulation
    public boolean cancelOrder(long orderId) {
        OrderNode node = orderIndex.remove(orderId);
        if (node == null) return false;

        PriceLevel level = node.parentLevel;
        level.remove(node);
        if (level.head == null) {
            NavigableMap<Long, PriceLevel> book = (node.side == Side.BUY) ? bids : asks;
            book.remove(level.priceCents);
        }
        return true;
    }
}
